const STORAGE_KEY="nuzha-admin-v1";
const seed={menu:structuredClone(window.NUZHA_MENU||[]),gallery:structuredClone(window.NUZHA_GALLERY||[]),reviews:[{en:"A generous table and warm welcome — exactly what a family meal should feel like.",ar:"مائدة كريمة وترحيب دافئ — تماماً كما يجب أن تكون الوجبة العائلية.",name:"Sample guest",rating:5},{en:"The platter made our gathering feel like a true celebration.",ar:"الصحن جعل اجتماعنا يبدو كاحتفال حقيقي.",name:"Sample guest",rating:5},{en:"Traditional flavours, beautifully served and made for sharing.",ar:"نكهات أصيلة، تقديم جميل، ومتعة المشاركة.",name:"Sample guest",rating:5}],settings:{englishName:"Nuzha Restaurant",arabicName:"مطعم ومطبخ النزهة",phone:"053 003 5292",whatsapp:"966530035292",facebook:"https://www.facebook.com/354392161334869",google:"https://www.google.com/maps/search/?api=1&query=NUZHA%20RESTAURANT%20Nairyah&query_place_id=ChIJLdhnS6y-zD8RepwxALWWiXo",tiktok:"https://www.tiktok.com/search?q=Nuzha%20Restaurant%20Nairyah",addressEn:"Prince Sultan bin Abdulaziz, Al Faisaliyah, King Fahd Road, Al Nairyah 37481, Saudi Arabia",addressAr:"الأمير سلطان بن عبدالعزيز، الفيصلية، شارع الملك فهد، النعيرية 37481"},updatedAt:null};
let data=load(),view="dashboard";
const workspace=document.querySelector("#adminWorkspace"),title=document.querySelector("#viewTitle"),eyebrow=document.querySelector("#viewEyebrow");
function load(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));return saved?{...structuredClone(seed),...saved,settings:{...seed.settings,...saved.settings}}:structuredClone(seed)}catch{return structuredClone(seed)}}
function esc(value=""){return String(value).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]))}
function image(src){return esc(src||"assets/logo.png")}
function setHeading(a,b){eyebrow.textContent=a;title.textContent=b}
function render(){document.querySelectorAll("#adminNav button").forEach(b=>b.classList.toggle("active",b.dataset.view===view));if(view==="dashboard")renderDashboard();if(view==="menu")renderMenu();if(view==="gallery")renderGallery();if(view==="reviews")renderReviews();if(view==="settings")renderSettings()}
function renderDashboard(){setHeading("ADMIN OVERVIEW","Good to see you.");workspace.innerHTML=`<div class="stat-grid"><article class="stat-card"><span>Menu items</span><strong>${data.menu.length}</strong></article><article class="stat-card"><span>Gallery photos</span><strong>${data.gallery.length}</strong></article><article class="stat-card"><span>Guest reviews</span><strong>${data.reviews.length}</strong></article><article class="stat-card"><span>Last saved</span><strong style="font-size:19px">${data.updatedAt?new Date(data.updatedAt).toLocaleString():"Not yet"}</strong></article></div><div class="quick-grid"><section class="panel"><div class="panel-head"><h2>Content health</h2><a href="index.html" target="_blank">Open site ↗</a></div><div class="check-list"><div><span>Official bilingual names</span><b>Ready</b></div><div><span>Menu currency labels</span><b>SAR / ر.س</b></div><div><span>Gallery entries with images</span><b>${data.gallery.filter(x=>x.src).length}/${data.gallery.length}</b></div><div><span>Google Business link</span><b>${data.settings.google?"Ready":"Missing"}</b></div></div></section><section class="panel"><h2>Local mode</h2><p>This panel is a working content editor. Saved changes appear on this device. Export a JSON backup before moving to another browser.</p><div class="toolbar"><button id="exportBtn">Export backup</button><label class="file-button">Import backup<input id="importFile" type="file" accept="application/json"></label></div></section></div>`;bindPortable()}
function renderMenu(){setHeading("MENU MANAGER","Dishes and prices.");workspace.innerHTML=`<div class="notice">Prices use Saudi Riyals. Keep “—” until the official CDR menu is supplied.</div><section class="panel"><div class="toolbar"><input id="menuSearch" placeholder="Search menu items"><button id="addMenu">+ Add menu item</button></div><div class="editor-list" id="menuList">${menuCards(data.menu)}</div></section>`;menuSearch.oninput=()=>{const q=menuSearch.value.toLowerCase();menuList.innerHTML=menuCards(data.menu,q)};addMenu.onclick=()=>{data.menu.unshift({category:"feasts",nameEn:"New item",nameAr:"صنف جديد",descEn:"Add an English description.",descAr:"أضف الوصف العربي.",price:"—",image:"assets/logo.png"});renderMenu()}}
function menuCards(items,q=""){return items.map((x,i)=>({x,i})).filter(({x})=>!q||`${x.nameEn} ${x.nameAr} ${x.category}`.toLowerCase().includes(q)).map(({x,i})=>`<article class="editor-card"><img src="${image(x.image)}" alt=""><div class="editor-fields"><input data-type="menu" data-i="${i}" data-key="nameEn" value="${esc(x.nameEn)}" aria-label="English name"><input dir="rtl" data-type="menu" data-i="${i}" data-key="nameAr" value="${esc(x.nameAr)}" aria-label="Arabic name"><textarea data-type="menu" data-i="${i}" data-key="descEn" aria-label="English description">${esc(x.descEn)}</textarea><textarea dir="rtl" data-type="menu" data-i="${i}" data-key="descAr" aria-label="Arabic description">${esc(x.descAr)}</textarea><select data-type="menu" data-i="${i}" data-key="category">${["feasts","rice","seafood","bbq","salads","kitchen","drinks"].map(c=>`<option ${x.category===c?"selected":""}>${c}</option>`).join("")}</select><input data-type="menu" data-i="${i}" data-key="price" value="${esc(x.price)}" placeholder="Price in SAR"><input class="wide" data-type="menu" data-i="${i}" data-key="image" value="${esc(x.image)}" placeholder="Image path"></div><button class="remove-btn" data-remove="menu" data-i="${i}" aria-label="Remove">×</button></article>`).join("")}
function renderGallery(){setHeading("GALLERY MANAGER","Images and captions.");workspace.innerHTML=`<section class="panel"><div class="toolbar"><input id="gallerySearch" placeholder="Search gallery"><button id="addGallery">+ Add image</button></div><div class="editor-list" id="galleryList">${galleryCards(data.gallery)}</div></section>`;gallerySearch.oninput=()=>{const q=gallerySearch.value.toLowerCase();galleryList.innerHTML=galleryCards(data.gallery,q)};addGallery.onclick=()=>{data.gallery.unshift({src:"gallery-images/your-image.jpg",category:"dishes",titleEn:"New gallery image",titleAr:"صورة جديدة"});renderGallery()}}
function galleryCards(items,q=""){return items.map((x,i)=>({x,i})).filter(({x})=>!q||`${x.titleEn} ${x.titleAr} ${x.category}`.toLowerCase().includes(q)).map(({x,i})=>`<article class="editor-card"><img src="${image(x.src)}" alt=""><div class="editor-fields"><input data-type="gallery" data-i="${i}" data-key="titleEn" value="${esc(x.titleEn)}"><input dir="rtl" data-type="gallery" data-i="${i}" data-key="titleAr" value="${esc(x.titleAr)}"><input data-type="gallery" data-i="${i}" data-key="category" value="${esc(x.category)}"><input data-type="gallery" data-i="${i}" data-key="src" value="${esc(x.src)}" placeholder="Image path"><small class="wide">Add the actual image file to <b>dist/gallery-images</b>, then enter its relative path here.</small></div><button class="remove-btn" data-remove="gallery" data-i="${i}">×</button></article>`).join("")}
function renderReviews(){setHeading("REVIEW MANAGER","Guest feedback.");workspace.innerHTML=`<section class="panel"><div class="toolbar"><p>Only publish genuine, verified customer feedback.</p><button id="addReview">+ Add review</button></div><div class="editor-list">${data.reviews.map((x,i)=>`<article class="editor-card"><div class="editor-fields" style="grid-column:1/3"><textarea data-type="reviews" data-i="${i}" data-key="en">${esc(x.en)}</textarea><textarea dir="rtl" data-type="reviews" data-i="${i}" data-key="ar">${esc(x.ar)}</textarea><input data-type="reviews" data-i="${i}" data-key="name" value="${esc(x.name)}" placeholder="Customer name"><select data-type="reviews" data-i="${i}" data-key="rating">${[5,4,3,2,1].map(n=>`<option ${+x.rating===n?"selected":""} value="${n}">${n} stars</option>`).join("")}</select></div><button class="remove-btn" data-remove="reviews" data-i="${i}">×</button></article>`).join("")}</div></section>`;addReview.onclick=()=>{data.reviews.unshift({en:"Add verified feedback.",ar:"أضف رأياً موثقاً.",name:"Customer",rating:5});renderReviews()}}
function renderSettings(){setHeading("SITE SETTINGS","Contact and identity.");const s=data.settings;workspace.innerHTML=`<section class="panel"><div class="settings-grid"><label>English name<input data-setting="englishName" value="${esc(s.englishName)}"></label><label>Arabic name<input dir="rtl" data-setting="arabicName" value="${esc(s.arabicName)}"></label><label>Phone<input data-setting="phone" value="${esc(s.phone)}"></label><label>WhatsApp number<input data-setting="whatsapp" value="${esc(s.whatsapp)}"></label><label>Facebook URL<input data-setting="facebook" value="${esc(s.facebook)}"></label><label>Google Business URL<input data-setting="google" value="${esc(s.google)}"></label><label class="wide">TikTok URL<input data-setting="tiktok" value="${esc(s.tiktok)}"></label><label class="wide">English address<textarea data-setting="addressEn">${esc(s.addressEn)}</textarea></label><label class="wide">Arabic address<textarea dir="rtl" data-setting="addressAr">${esc(s.addressAr)}</textarea></label></div></section><section class="panel"><div class="toolbar"><button id="exportBtn">Export JSON backup</button><label class="file-button">Import JSON backup<input id="importFile" type="file" accept="application/json"></label></div></section><section class="panel danger-zone"><h2>Reset local content</h2><p>Restore the built-in website data on this browser. Export a backup first if needed.</p><button id="resetAll">Reset everything</button></section>`;bindPortable();resetAll.onclick=()=>{if(confirm("Reset all admin content on this browser?")){data=structuredClone(seed);persist();render();toast("Content reset")}}}
function persist(){data.updatedAt=new Date().toISOString();localStorage.setItem(STORAGE_KEY,JSON.stringify(data));const existing=JSON.parse(localStorage.getItem("nuzha-data")||"{}");existing.phone=data.settings.phone;existing.socials={facebook:data.settings.facebook,google:data.settings.google,tiktok:data.settings.tiktok};existing.menu=data.menu.slice(0,5).map((x,i)=>({id:i+1,en:x.nameEn,ar:x.nameAr,descEn:x.descEn,descAr:x.descAr,price:x.price==="—"?"Ask us":`${x.price} SAR`,priceAr:x.price==="—"?"حسب الطلب":`${x.price} ر.س`,cat:({feasts:"Feasts",rice:"Rice",seafood:"Seafood",bbq:"Grill",salads:"Feasts",kitchen:"Feasts",drinks:"Feasts"}[x.category]||"Feasts"),img:x.image}));existing.reviews=data.reviews;localStorage.setItem("nuzha-data",JSON.stringify(existing))}
function bindPortable(){const ex=document.querySelector("#exportBtn"),im=document.querySelector("#importFile");if(ex)ex.onclick=()=>{const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:"application/json"}));a.download="nuzha-admin-backup.json";a.click();URL.revokeObjectURL(a.href)};if(im)im.onchange=async e=>{try{const incoming=JSON.parse(await e.target.files[0].text());if(!incoming.menu||!incoming.gallery||!incoming.settings)throw new Error();data=incoming;persist();render();toast("Backup imported")}catch{alert("This is not a valid Nuzha admin backup.")}}}
function toast(message){const el=document.querySelector("#toast");el.textContent=message;el.classList.add("show");setTimeout(()=>el.classList.remove("show"),2200)}
document.querySelector("#adminNav").onclick=e=>{const b=e.target.closest("button[data-view]");if(!b)return;view=b.dataset.view;render()};document.querySelector("#saveAll").onclick=()=>{persist();toast("Changes saved on this browser")};workspace.addEventListener("input",e=>{const el=e.target;if(el.dataset.setting)data.settings[el.dataset.setting]=el.value;if(el.dataset.type){const value=el.dataset.key==="rating"?+el.value:el.value;data[el.dataset.type][+el.dataset.i][el.dataset.key]=value}});workspace.addEventListener("click",e=>{const b=e.target.closest("[data-remove]");if(!b)return;data[b.dataset.remove].splice(+b.dataset.i,1);render()});render();
